const $=(s,root=document)=>root.querySelector(s);
const $$=(s,root=document)=>[...root.querySelectorAll(s)];
const dialog=$('#info-dialog');
const make=(tag,text,className)=>{const node=document.createElement(tag);if(text!==undefined)node.textContent=text;if(className)node.className=className;return node;};
const info={
  about:{title:'Your next chapter starts here.',p:['JobsAI is one app with two halves: a career agent to help you find and prepare for opportunities, and clients and workers completing clearly scoped work tasks.','The career workspace helps you explore opportunities and prepare for your next step. Work Tasks lists funded jobs and lets a wallet claim one. Job creation, funding, submissions, revisions, acceptance, and disputes are supported through the JobsAI API.']},
  availability:{title:'Designed for work, wherever you are.',p:['The career experience is designed around employers’ public job boards and a workspace that works across screen sizes. Geographic and service availability will be confirmed at launch.','Payment options described in the specification remain planned and require provider and regional verification. The career workspace does not connect a wallet. In Work Tasks, wallet sign-in is used to claim an existing funded job; the claim itself sends no transaction.']},
  factlock:{title:'Your story. With the facts intact.',p:['The planned fact lock aligns each generated claim with the experience, education, skills, and links in your profile. If it cannot trace a claim, it removes it or asks you to confirm it.','Claims are checked against your profile. Unsupported claims are flagged or removed for your review.','Fact checking can miss subtle overstatements. You review every document, then choose whether to submit it on the employer’s own site.'],link:['See the example workspace','workspace.html']},
  payment:{title:'A clear finish line. A fair review.',p:['A client sets the task requirements and payment amount before funding a job. A worker submits work for the client to review.','Client acceptance starts payment. Clients can request repeated revisions. Automated rule checks, model-assisted review, and a timed review window with auto-acceptance are planned, not active.','Either participant can open a dispute. The job is locked while an authorized JobsAI reviewer checks its history and decides whether to pay the worker or refund the client. Automatic refunds for failed checks, missed deadlines, or late team decisions are planned, not active. A client can cancel only before a worker claims the funded job.','Job funding, submissions, revisions, acceptance, and dispute resolution are handled by the JobsAI backend.']},
  pass:{title:'Career Pass. A little more support.',p:['Planned price: $9 per month. Includes 60 tailored applications per month, unlimited mock interviews, and practice tasks. The limit of 10 tailored applications per day still applies. Cancel within 14 days of the first payment for a full refund; after that, unused full months are refunded at the price paid.','Career Pass checkout is not available yet. Open the workspace to explore career tools.'],link:['Open the dashboard','workspace.html']},
  packs:{title:'Five applications. One small pack.',p:['Planned price: $4 for five tailored applications, without a Career Pass. Each document must pass its checks before a credit counts. Unused credits are refundable.','Applications are based on your own facts and remain subject to the 10-per-day limit. You review and submit each one yourself. Career application packs are not available for purchase yet.'],link:['Open the job market','workspace.html']},
  custom:{title:'A plan for the task you have in mind.',p:['Custom work is planned for J5. Describe your desired outcome and receive a plan, a fixed quote, a delivery time, and acceptance checks before funding the job.','Recurring jobs are also planned, with both a per-run price cap and an overall cap set by you. The work board lists funded jobs that are ready to claim.'],link:['Browse funded work','workspace.html?tab=jobs']},
  privacy:{title:'Privacy at JobsAI.',p:['Career roles and task templates use local example data. There is no analytics, CV upload, payment collection, or remote AI generation. If you connect a wallet to claim a live funded task, the site creates a JobsAI session and stores its token in this browser tab. Your tracker choices and motion preference stay in local storage.','Text typed into the interview practice stays in the page and is not sent to a server or saved. You can reset local workspace data from the workspace settings.','Career profiles and remote AI services are not connected. Live job submissions and dispute records are stored to operate the job and are not automatically deleted 30 days after settlement. Uploaded images follow the image-storage account’s retention settings. A 30-day deletion policy is planned, not active.']},
  terms:{title:'About using JobsAI.',p:['The career workspace uses local career listings and tracker data. The Work Tasks board connects to funded jobs that can be claimed with a wallet. Career applications and Career Pass checkout are not available yet.','The product specification describes intended capabilities and pricing. Availability and final service terms will be confirmed before launch. JobsAI cannot guarantee interviews, job offers, or error-free work.']},
  'guide-cv':{title:'A stronger CV starts with real facts.',p:['Start with a short list of projects, responsibilities, tools, and outcomes you can explain. Keep useful numbers only when you can support them.','Read the role’s requirements. Put the most relevant experience first, using concrete examples rather than broad claims. A career change does not require inventing a past job.','Check every sentence before sending. A good draft should sound like you, be easy to read, and stand up to a follow-up question.'],link:['See the fact-lock example','workspace.html']},
  'guide-checks':{title:'Make “done” something you can check.',p:['Agree on the format, required fields, source material, and scope before work begins. “Make it better” is hard to verify. “Remove duplicate rows and standardise dates without changing totals” gives everyone a clear target.','Separate mechanical checks from judgment. A table can have all its columns and still need a human review of whether the conclusions are useful.','Review the output and its evidence together. Passing the stated checks does not mean that a result is perfect.'],link:['Review a work delivery','workspace.html?tab=jobs']},
  'guide-interview':{title:'Practise the work behind the words.',p:['Pick a real project and explain the problem, your own contribution, a decision you made, and the result. Be clear about what your teammates did too.','Prepare questions about the team’s goals and how success in the role is measured. A useful interview helps you assess the fit as well.','Practice is for finding gaps and gaining clarity. You do not need a memorised performance.'],link:['Try a practice question','workspace.html?tab=interviews']}
};
function openInfo(key){const entry=info[key];if(!entry)return;$('#dialog-kicker').textContent='GET TO KNOW JOBSAI';$('#dialog-title').textContent=entry.title;const body=$('#dialog-body');body.replaceChildren(...entry.p.map(p=>make('p',p)));const actions=$('#dialog-actions');actions.replaceChildren();if(entry.link){const a=make('a',entry.link[0],'pill primary');a.href=entry.link[1];actions.append(a);}dialog.showModal();}
$$('[data-info]').forEach(b=>b.addEventListener('click',()=>openInfo(b.dataset.info)));
$$('[data-start]').forEach(b=>b.addEventListener('click',()=>{
 $('#dialog-kicker').textContent='WELCOME TO JOBSAI';$('#dialog-title').textContent='What’s your next move?';$('#dialog-body').replaceChildren(make('p','Open the dashboard to browse funded work. Connect a wallet to claim a job.'));
 const choices=make('div',undefined,'dialog-choices');
 [['Find my next role','Explore matches, a fact-checked application, interview practice, and your tracker.','workspace.html'],['Get a task done','Browse funded work and review the job requirements before claiming.','workspace.html?tab=jobs']].forEach(([title,copy,url])=>{const a=make('a',undefined,'choice-card');a.href=url;a.append(make('strong',title),make('span',copy),make('b','→'));choices.append(a);});
 $('#dialog-body').append(choices);$('#dialog-actions').replaceChildren();dialog.showModal();
}));
$$('[data-job]').forEach(b=>b.addEventListener('click',()=>{
 $('#dialog-kicker').textContent='WORK TASK TEMPLATE';$('#dialog-title').textContent=b.dataset.job;$('#dialog-body').replaceChildren(make('p','Start with the result you want, the source files, and any format requirements. Each funded job has a client-set amount and agreed acceptance criteria.'),make('p','Review the scope and acceptance criteria for funded work in the dashboard.'));
 const a=make('a','View funded work','pill primary');a.href=`workspace.html?tab=jobs&template=${encodeURIComponent(b.dataset.job)}`;$('#dialog-actions').replaceChildren(a);dialog.showModal();
}));
$('.dialog-close').addEventListener('click',()=>dialog.close());
dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});
const navToggles=$$('.nav-toggle');
function closeNav(){navToggles.forEach(b=>{b.setAttribute('aria-expanded','false');document.getElementById(b.getAttribute('aria-controls')).hidden=true;});}
navToggles.forEach(b=>b.addEventListener('click',()=>{const open=b.getAttribute('aria-expanded')==='true';closeNav();if(!open){b.setAttribute('aria-expanded','true');document.getElementById(b.getAttribute('aria-controls')).hidden=false;}}));
document.addEventListener('click',e=>{if(!e.target.closest('.nav-group'))closeNav();});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){const expanded=navToggles.find(b=>b.getAttribute('aria-expanded')==='true');closeNav();if(expanded)expanded.focus();closeMobile();}});
const menu=$('.menu-button');function closeMobile(){menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label','Open menu');$('#mobile-nav').hidden=true;}
menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')==='true';menu.setAttribute('aria-expanded',String(!open));menu.setAttribute('aria-label',open?'Open menu':'Close menu');$('#mobile-nav').hidden=open;});
$$('a[href^="#"]').forEach(a=>a.addEventListener('click',()=>{closeNav();closeMobile();}));
const audienceNotes=['A fresh start, on your terms.','Your skills. A new direction.','More room for your best work.','One less thing on the list.'];
$$('[data-audience]').forEach(b=>b.addEventListener('click',()=>{$$('[data-audience]').forEach(other=>{const selected=other===b;other.setAttribute('aria-expanded',String(selected));other.lastElementChild.textContent=selected?'−':'+';other.parentElement.classList.toggle('active',selected);document.getElementById(other.getAttribute('aria-controls')).hidden=!selected;});$('#audience-note').textContent=audienceNotes[Number(b.dataset.audience)];}));
const header=$('.header'),floating=$('.floating-cta');let queued=false;
function updateScroll(){header.classList.toggle('scrolled',window.scrollY>25);const heroEnd=$('.hero-actions').getBoundingClientRect().bottom;const footerTop=$('.final-cta').getBoundingClientRect().top;floating.classList.toggle('visible',heroEnd<0&&footerTop>window.innerHeight*.8);queued=false;}
window.addEventListener('scroll',()=>{if(!queued){queued=true;requestAnimationFrame(updateScroll);}},{passive:true});updateScroll();
let paused=false;try{paused=localStorage.getItem('jobsai-motion')==='paused';}catch{}
const motionButton=$('#motion-toggle');function syncMotion(){document.body.classList.toggle('motion-paused',paused);motionButton.setAttribute('aria-pressed',String(paused));motionButton.textContent=paused?'Resume motion':'Pause motion';document.dispatchEvent(new Event('jobsai:motion'));}
motionButton.addEventListener('click',()=>{paused=!paused;try{localStorage.setItem('jobsai-motion',paused?'paused':'active');}catch{}syncMotion();});syncMotion();
if('IntersectionObserver'in window&&!matchMedia('(prefers-reduced-motion: reduce)').matches&&!paused){document.body.classList.add('js-motion');const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.remove('pending');observer.unobserve(entry.target);}}),{threshold:.06});$$('.section-heading,.feature-row,.career-card,.job-card,.process-card,.resource-card').forEach(el=>{el.classList.add('reveal');if(el.getBoundingClientRect().top>window.innerHeight)el.classList.add('pending');observer.observe(el);});}
